import java.util.Scanner;
public class PrimeDigitSquareProduct
{
  public static void main(String args[])
  {
    Scanner sc = new Scanner(System.in);
    System.out.print("Enter a number: ");
    int num = sc.nextInt();
    boolean prime = (num > 1);
    for(int i=2; i<=num/2; i++)
    {
      if(num % i == 0)
      { prime = false; break; }
    }
    if(prime)
    {
      long product = 1;
      int n = num;
      while(n > 0)
      {
        int d = n % 10;
        product *= (d * d);
        n /= 10;
      }
      System.out.println("Product of squares of digits = "+product);
    }
    else
      System.out.println(num+" is a Composite Number");
  }
}

