  {
    Scanner sc = new Scanner(System.in);
    System.out.print("Enter n: ");
    int n = sc.nextInt();
    double sum = 0;
    for(int i=2; i<=n+1; i++)
    {
      double numerator = 0;
      for(int k=1; k<=i; k++) numerator += k;
      double denom = 1;
      for(int k=1; k<=i; k++) denom *= k;
      sum += numerator/denom;
    }
    System.out.println("Sum = "+sum);
  }
}

import java.util.Scanner;
public class PrimeReverseOrFactors
{
  public static void main(String args[])
  {
    Scanner sc = new Scanner(System.in);
    System.out.print("Enter a number: ");
    int num = sc.nextInt();
    boolean prime = (num > 1);
    for(int i=2; i<=num/2; i++)
      if(num % i == 0) { prime = false; break; }
    if(prime)
    {
      int n = num, rev = 0;
      while(n > 0)
      {
        rev = rev*10 + n%10;
        n /= 10;
      }
      System.out.println(num+" is Prime. Reverse = "+rev);
    }
    else
    {
      System.out.println(num+" is Composite. Factors are:");
      for(int i=1; i<=num; i++)
        if(num % i == 0) System.out.print(i+" ");
    }
  }
}

